    /**
     * Retrieves the daily prompt cycling smoothly through the calendar year.
     */
    fun getTodayPrompt(): String {
        val calendar = Calendar.getInstance()
        val dayOfYear = calendar.get(Calendar.DAY_OF_YEAR)
        return getPromptByIndex(dayOfYear - 1)
    }

    /**
     * Retrieves prompt by index, cycling gracefully across the 1,000 prompts.
     */
    fun getPromptByIndex(index: Int): String {
        if (allPrompts.isEmpty()) return "How are you feeling right now in this quiet moment?"
        val normalizedIndex = ((index % allPrompts.size) + allPrompts.size) % allPrompts.size
        return allPrompts[normalizedIndex]
    }

    /**
     * Gets a random prompt for spontaneous reflections.
     */
    fun getRandomPrompt(): String {
        return allPrompts.random()
    }

    /**
     * Cycles to the next prompt given a current index.
     */
    fun getNextPrompt(currentIndex: Int): Pair<Int, String> {
        val nextIndex = (currentIndex + 1) % allPrompts.size
        return Pair(nextIndex, allPrompts[nextIndex])
    }

    /**
     * Returns the total count of prompts.
     */
    fun getCount(): Int = allPrompts.size
}
